pragma solidity ^0.8.24;

// src/IAgentSpendMandate.sol
// Copyright (c) CreditChain Research Team. All rights reserved.

/// @title IAgentSpendMandate — the ERC-AGM standard interface
/// @notice Canonical interface for a chain-enforced, bounded, revocable
/// spending mandate granted by an owner to an autonomous agent.
///
/// An implementation custodies value on behalf of an owner and lets a delegated
/// `agent` spend it autonomously, while the contract enforces a budget cap, a
/// per-transaction maximum, a rolling-window rate limit, an optional recipient
/// allowlist, and an expiry. The owner can revoke at any time and reclaim the
/// unspent balance. No party other than the mandate's owner may move its funds.
///
/// See ERC-AGM (`docs/standards/ERC-AGM.md`) for the full specification.
/// Reference implementation: `AgentSpendVault.sol`.
interface IAgentSpendMandate {
    /// @dev The full state of a mandate. Implementations MAY store this layout
    /// differently but MUST expose it through `mandate(uint256)`.
    struct Mandate {
        address owner;
        address agent;
        uint256 budget;
        uint256 spent;
        uint256 balance;
        uint256 perTxMax;
        uint256 windowLimit;
        uint64 windowSeconds;
        uint64 windowStart;
        uint256 windowSpent;
        uint64 expiry;
        bool allowlistEnabled;
        bool revoked;
    }

    // ── events ───────────────────────────────────────────────────────────────

    event MandateCreated(
        uint256 indexed mandateId,
        address indexed owner,
        address indexed agent,
        uint256 budget,
        uint256 perTxMax,
        uint256 windowLimit,
        uint64 windowSeconds,
        uint64 expiry,
        bool allowlistEnabled
    );
    event MandateFunded(uint256 indexed mandateId, address indexed from, uint256 amount, uint256 newBalance);
    event RecipientAllowed(uint256 indexed mandateId, address indexed recipient, bool allowed);
    event AgentPayment(
        uint256 indexed mandateId,
        address indexed agent,
        address indexed recipient,
        uint256 amount,
        bytes32 taskRef,
        uint256 totalSpent
    );
    event MandateRevoked(uint256 indexed mandateId, address indexed owner, uint256 refunded);
    event Withdrawn(uint256 indexed mandateId, address indexed owner, uint256 amount);

    // ── errors ───────────────────────────────────────────────────────────────

    error NotOwner();
    error NotAgent();
    error MandateInactive();
    error ZeroAddress();
    error ZeroAmount();
    error BudgetExceeded();
    error PerTxExceeded();
    error WindowExceeded();
    error RecipientNotAllowed();
    error InsufficientBalance();
    error TransferFailed();

    // ── mutating ─────────────────────────────────────────────────────────────

    /// @notice Create and fund a mandate. The value sent becomes its balance.
    /// MUST emit {MandateCreated} (and {MandateFunded} if value > 0).
    function createMandate(
        address agent,
        uint256 budget,
        uint256 perTxMax,
        uint256 windowLimit,
        uint64 windowSeconds,
        uint64 expiry,
        bool allowlistEnabled
    ) external payable returns (uint256 mandateId);

    /// @notice Top up a mandate's balance. Implementations MAY allow anyone to fund.
    function fundMandate(uint256 mandateId) external payable;

    /// @notice Owner sets allowlist membership for a recipient. MUST revert {NotOwner}
    /// for non-owners.
    function allowRecipient(uint256 mandateId, address recipient, bool allowed) external;

    /// @notice The agent spends to a recipient. MUST be callable only by the
    /// mandate's agent and MUST enforce every rail (expiry, allowlist, per-tx,
    /// budget, balance, rolling window), reverting with the corresponding error
    /// and moving no value on violation. MUST emit {AgentPayment} on success.
    function spend(uint256 mandateId, address recipient, uint256 amount, bytes32 taskRef) external;

    /// @notice Owner kill switch: deactivates the mandate and refunds the unspent
    /// balance. After this the agent MUST NOT be able to spend. MUST emit {MandateRevoked}.
    function revoke(uint256 mandateId) external;

    /// @notice Owner reclaims part of the unspent balance without revoking.
    /// MUST emit {Withdrawn}.
    function withdraw(uint256 mandateId, uint256 amount) external;

    // ── views ────────────────────────────────────────────────────────────────

    /// @notice The full mandate record.
    function mandate(uint256 mandateId) external view returns (Mandate memory);

    /// @notice The most the agent could spend right now under all rails combined.
    function spendableNow(uint256 mandateId) external view returns (uint256);

    /// @notice Number of mandates created (also the id of the most recent).
    function mandateCount() external view returns (uint256);

    /// @notice Whether a recipient is allowlisted for a mandate.
    function allowlisted(uint256 mandateId, address recipient) external view returns (bool);
}

// src/AgentReputation.sol
// Copyright (c) CreditChain Research Team. All rights reserved.

/// @title AgentReputation
/// @notice On-chain, mandate-backed reputation for AI agents — the substrate for
/// "reputation becomes collateral" (agents that have provably served real
/// spending mandates can earn larger ones).
///
/// Reputation is built **only** from real `AgentSpendVault` mandates:
///   - the attester must be the mandate's actual owner,
///   - the mandate must have settled spend (`spent > 0`),
///   - each mandate can be attested at most once.
///
/// So an agent's record cannot be faked by spamming a counter — every point is
/// backed by value the agent actually moved under a human-granted mandate,
/// verified against the vault at attestation time.
///
/// @dev v1 is a pure registry (holds no funds). It is intentionally simple: it
/// records *what happened* on-chain. Sybil-resistance of the *attesters* (e.g.
/// weighting by the attester's own stake/reputation) is a consumer concern and
/// a future extension; consumers may also read the raw fields and compute their
/// own score rather than trust `score()`.
contract AgentReputation {
    /// The AgentSpendVault (ERC-AGM) this registry draws mandate facts from.
    IAgentSpendMandate public immutable vault;

    struct Reputation {
        uint256 mandatesServed; // distinct mandates the agent settled spend under
        uint256 valueSettled;   // cumulative CCC (wei) settled across those mandates
        uint64 firstSeen;       // timestamp of first attestation
        uint64 lastActivity;    // timestamp of latest attestation
    }

    mapping(address => Reputation) private _rep;
    /// mandateId => attested, so each mandate contributes at most once.
    mapping(uint256 => bool) public attestedMandate;

    event AgentAttested(
        address indexed agent,
        address indexed owner,
        uint256 indexed mandateId,
        uint256 settled,
        uint256 totalValueSettled,
        uint256 mandatesServed
    );

    error NotMandateOwner();
    error NoSettledSpend();
    error AlreadyAttested();
    error ZeroVault();

    constructor(address vault_) {
        if (vault_ == address(0)) revert ZeroVault();
        vault = IAgentSpendMandate(vault_);
    }

    /// @notice The owner of a vault mandate attests its agent's completed work.
    /// Pulls the mandate from the vault, checks caller is the owner and that the
    /// agent actually spent, and credits the agent's reputation once per mandate.
    function attestMandate(uint256 mandateId) external {
        if (attestedMandate[mandateId]) revert AlreadyAttested();

        IAgentSpendMandate.Mandate memory m = vault.mandate(mandateId);
        if (msg.sender != m.owner) revert NotMandateOwner();
        if (m.spent == 0) revert NoSettledSpend();

        attestedMandate[mandateId] = true;

        Reputation storage r = _rep[m.agent];
        if (r.firstSeen == 0) r.firstSeen = uint64(block.timestamp);
        r.mandatesServed += 1;
        r.valueSettled += m.spent;
        r.lastActivity = uint64(block.timestamp);

        emit AgentAttested(m.agent, m.owner, mandateId, m.spent, r.valueSettled, r.mandatesServed);
    }

    // ─────────────────────────── views ───────────────────────────

    function reputation(address agent) external view returns (Reputation memory) {
        return _rep[agent];
    }

    /// @notice A naive, monotonic reputation score: 100 points per mandate served
    /// plus one point per whole CCC settled. Provided for convenience; consumers
    /// that need different weighting should read `reputation()` and compute their
    /// own. Never decreases as an agent does more verified work.
    function score(address agent) external view returns (uint256) {
        Reputation storage r = _rep[agent];
        return r.mandatesServed * 100 + r.valueSettled / 1e18;
    }
}

// src/ReputationGate.sol
// Copyright (c) CreditChain Research Team. All rights reserved.

/// @title ReputationGate
/// @notice Reputation-gated agent spending — "reputation becomes collateral"
/// made enforceable. This closes the loop between the two CreditChain
/// agent-finance primitives: `AgentSpendVault` bounds *how much* an agent may
/// spend, and `AgentReputation` records *what it has provably done*. This
/// contract makes the second a precondition of the first.
///
/// How it composes without touching either deployed contract: the owner creates
/// a mandate in the vault whose `agent` is **this gate**, then registers an
/// operator (the real agent) plus a minimum reputation score. The operator
/// spends via {spendVia}, which checks reputation and forwards to the vault —
/// so the vault's own rails (budget, per-tx, window, allowlist, expiry, revoke)
/// still apply underneath, unchanged and unweakened.
///
/// The result: an agent must *earn* the right to spend, and keeps it only while
/// its on-chain record holds. An owner can raise the bar at any time, and the
/// vault owner's instant revoke remains the ultimate kill switch.
///
/// @dev This gate holds no funds of its own. It is a pure authorisation layer;
/// all value stays in the vault until the vault itself releases it.
contract ReputationGate {
    IAgentSpendMandate public immutable vault;
    AgentReputation public immutable reputation;

    struct Policy {
        address owner;       // who configured this gate entry (the mandate owner)
        address operator;    // the real agent permitted to spend
        uint256 minScore;    // required AgentReputation.score(operator)
        bool enabled;        // owner can disable without touching the vault
    }

    /// mandateId => policy
    mapping(uint256 => Policy) private _policies;

    event PolicySet(
        uint256 indexed mandateId,
        address indexed owner,
        address indexed operator,
        uint256 minScore
    );
    event PolicyDisabled(uint256 indexed mandateId, address indexed owner);
    event GatedSpend(
        uint256 indexed mandateId,
        address indexed operator,
        address indexed recipient,
        uint256 amount,
        uint256 operatorScore
    );

    error NotMandateOwner();
    error NotOperator();
    error PolicyNotEnabled();
    error InsufficientReputation(uint256 score, uint256 required);
    error ZeroAddress();
    error GateNotMandateAgent();

    constructor(address vault_, address reputation_) {
        if (vault_ == address(0) || reputation_ == address(0)) revert ZeroAddress();
        vault = IAgentSpendMandate(vault_);
        reputation = AgentReputation(reputation_);
    }

    /// @notice Mandate owner authorises `operator` to spend from `mandateId`
    /// once its reputation score reaches `minScore`. Re-callable to raise or
    /// lower the bar, or to rotate the operator.
    /// @dev Requires that this gate is actually the mandate's agent, otherwise
    /// the policy could never be exercised and would be misleading on-chain.
    function setPolicy(uint256 mandateId, address operator, uint256 minScore) external {
        if (operator == address(0)) revert ZeroAddress();
        IAgentSpendMandate.Mandate memory m = vault.mandate(mandateId);
        if (msg.sender != m.owner) revert NotMandateOwner();
        if (m.agent != address(this)) revert GateNotMandateAgent();

        _policies[mandateId] = Policy({
            owner: msg.sender,
            operator: operator,
            minScore: minScore,
            enabled: true
        });
        emit PolicySet(mandateId, msg.sender, operator, minScore);
    }

    /// @notice Owner disables the gate entry. The vault mandate is untouched —
    /// use the vault's own `revoke` to reclaim funds.
    function disablePolicy(uint256 mandateId) external {
        Policy storage p = _policies[mandateId];
        if (msg.sender != p.owner) revert NotMandateOwner();
        p.enabled = false;
        emit PolicyDisabled(mandateId, msg.sender);
    }

    /// @notice The operator spends through the gate. Reputation is checked at
    /// call time — an agent that has not yet earned its score cannot spend, and
    /// a raised bar takes effect immediately.
    function spendVia(uint256 mandateId, address recipient, uint256 amount, bytes32 taskRef)
        external
    {
        Policy storage p = _policies[mandateId];
        if (!p.enabled) revert PolicyNotEnabled();
        if (msg.sender != p.operator) revert NotOperator();

        uint256 score = reputation.score(msg.sender);
        if (score < p.minScore) revert InsufficientReputation(score, p.minScore);

        // The vault re-checks every rail; this gate only adds a precondition.
        vault.spend(mandateId, recipient, amount, taskRef);
        emit GatedSpend(mandateId, msg.sender, recipient, amount, score);
    }

    // ─────────────────────────── views ───────────────────────────

    function policy(uint256 mandateId) external view returns (Policy memory) {
        return _policies[mandateId];
    }

    /// @notice Whether `operator` currently satisfies the gate for `mandateId`.
    /// Useful for wallets/UIs to show "eligible" before a call is attempted.
    function isEligible(uint256 mandateId, address operator) external view returns (bool) {
        Policy storage p = _policies[mandateId];
        return p.enabled && p.operator == operator && reputation.score(operator) >= p.minScore;
    }
}
